window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q11"]=window.__LIBQ["the-gioi-hoan-my"]["q11"]||{};window.__LIBQ["the-gioi-hoan-my"]["q11"]["map"]={"updatedAt":"2026-07-25","count":130,"nodes":[{"id":"thien-kiep-tang-thu-muoi","name":"Thiên kiếp tầng thứ mười","cn":"","capDo":"khac","parentId":"thien","blurb":"Tầng thiên kiếp nơi Thạch Hạo và Ninh Xuyên quyết chiến quanh Lôi trì.","detail":"Khu vực này có biển sấm, các sinh linh do lôi điện hóa thành và Trảm Tiên đài. Cuộc giao chiến của Thạch Hạo với Ninh Xuyên khiến toàn tầng bạo động trước khi lôi kiếp và Lôi trì cùng biến mất.","theLucLienQuan":[],"nguon":["@c1001"]},{"id":"tieu-thien-the-gioi-dien-ra-quyet-chien","name":"Tiểu thiên thế giới diễn ra quyết chiến","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Tiểu thiên thế giới nơi Thạch Hạo và Ninh Xuyên tiến hành trận quyết chiến.","detail":"Nơi đây đồng thời diễn ra hỗn chiến giữa các Giáo chủ muốn tranh đoạt Lôi Kiếp dịch và những người bảo vệ Thạch Hạo. Tin tức trận đấu thu hút thiên tài cùng dân bản địa từ nhiều tiểu thiên thế giới khác kéo đến quan chiến.","theLucLienQuan":["Bát Tí Hồn tộc","Mỹ Nhân tộc","Ngân Huyết"],"nguon":["@c1002"]},{"id":"hon-dao","name":"Hồn đạo","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Nơi Thạch Hạo đưa các Giáo chủ bản địa trở về sau khi Ninh Xuyên thoát khỏi Tiên cổ.","detail":"Tại Hồn đạo, Thạch Hạo phân chia Lôi Kiếp dịch cho bốn Giáo chủ lạ mặt để họ hóa giải nguyền rủa, qua đó tập hợp lực lượng gồm chín Giáo chủ hộ tống.","theLucLienQuan":["Bát Tí Hồn tộc","Mỹ Nhân tộc"],"nguon":["@c1003"]},{"id":"ba-ngan-canh-hoa-dai-dao","name":"Ba ngàn cánh hoa đại Đạo","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Cơ chế truyền tống đưa các thiên tài sống sót rời khỏi Tiên cổ khi cuộc thí luyện kết thúc.","detail":"Khi Tiên cổ bị nối thông với ngoại giới, ba ngàn cánh hoa đại Đạo phát sáng và cuốn toàn bộ người dự thi còn sống trở về nơi xuất phát. Ánh sáng truyền tống cũng tách Thạch Hạo khỏi chín Giáo chủ vừa được hắn tập hợp.","theLucLienQuan":[],"nguon":["@c1003"]},{"id":"cam-khu-sau-trong-khu-khong-nguoi","name":"Cấm khu sâu trong khu không người","cn":"","capDo":"vuc","parentId":"khu-khong-nguoi","blurb":"Vùng sâu nguy hiểm trong khu không người, nơi các sinh linh mạnh như Ứng Long, Nhai Tí và Cửu đầu điểu xuất hiện.","detail":"Nhóm sinh linh từ Cấm khu tiến tới lối ra Tiên cổ, bắt các thiên tài và giao chiến với những Giáo chủ đang phong tỏa khu vực.","theLucLienQuan":[],"nguon":["@c1004"]},{"id":"khu-vuc-phong-toa-ngoai-tien-co","name":"Khu vực phong tỏa ngoài Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Chiến trường bên ngoài Tiên cổ bị nhiều Giáo chủ dùng hàng loạt trận pháp phong tỏa.","detail":"Tại đây, Thập Quan vương dùng cây non Thế Giới thụ phá vòng vây và được người của Đế tộc đưa đi. Sau đó, Thạch Hạo bị nhiều Giáo chủ bao vây công kích; đường hầm thời gian của hắn cũng bị trận pháp cắt đứt.","theLucLienQuan":["Đế tộc","Thú hải","Hỏa Vân động","Yêu Long đạo môn","Thiên Nhân tộc","Minh thổ","Thần miếu","La Phù chân cốc","Chí Tôn đạo tràng"],"nguon":["@c1005"]},{"id":"con-mon","name":"Côn môn","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Thạch Hạo từng mua tín vật để giành tư cách tiến vào Tiên cổ.","detail":"Lão già nát rượu từng bán tín vật cho Thạch Hạo tại đây được nhận ra là thứ thân của Côn Bằng tử.","theLucLienQuan":["Côn môn"],"nguon":["@c1007"]},{"id":"ba-ngan-chau","name":"Ba ngàn châu","cn":"","aliases":["Ba ngàn đại châu thượng giới","Ba ngàn đạo châu","Ba ngàn châu thượng giới"],"capDo":"chau","parentId":null,"blurb":"Vùng rộng lớn của thượng giới gồm ba ngàn đại châu.","detail":"Chủ nhân Ma Quỳ viên từng trải qua nhiều cuộc đại chiến và gây dựng uy danh trong phạm vi ba ngàn đại châu thượng giới.","theLucLienQuan":["Ma Quỳ viên"],"nguon":["@c1008"]},{"id":"vung-nui-chien-truong","name":"Vùng núi chiến trường","cn":"","capDo":"khac","parentId":"ba-ngan-chau","blurb":"Vùng núi nơi liên quân Giáo chủ bố trí hàng chục tầng đại trận và giao chiến với Liễu Thần.","detail":"Cú rơi của điện đồng xuyên thủng nhiều tầng đại trận, khiến núi non nổ tung, hư không vỡ nát và hình thành một vực sâu không thấy đáy.","theLucLienQuan":["Tiên điện","Kiếm cốc","Tây Phương giáo","Yêu Long đạo môn","Thiên quốc","Minh thổ"],"nguon":["@c1010"]},{"id":"ben-trong-dien-dong","name":"Bên trong điện đồng","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian bên trong điện đồng, nơi chí tôn Tiên điện khoanh chân kết ấn. Liễu Thần bước vào đây để trực tiếp truy sát đối phương.","detail":"Chí tôn Tiên điện điều khiển chí bảo và hiển hóa Nhân Tiên từ không gian này. Cuối chương, Liễu Thần đặt một chân vào bên trong dù có nguy cơ bị nhốt trong chính chí bảo của đối phương.","theLucLienQuan":["Tiên điện"],"nguon":["@c1011"]},{"id":"chien-truong-hon-chien-thuong-gioi","name":"Chiến trường hỗn chiến thượng giới","cn":"","capDo":"khac","parentId":"ba-ngan-chau","blurb":"Khu vực quanh điện đồng nơi các Giáo chủ chia phe và giao chiến dữ dội.","detail":"Một số cường giả chuyển sang công kích Thạch Hạo trong khi phe Côn Bằng tử và chín đại Giáo chủ Tiên cổ liên thủ bảo vệ cậu. Va chạm giữa các chí bảo và cường giả khiến bầu trời cùng hư không bị phá nát.","theLucLienQuan":["Tiên điện","Chín đại Giáo chủ Tiên cổ"],"nguon":["@c1012"]},{"id":"canh-cua-nguyen-thuy","name":"Cánh cửa Nguyên Thủy","cn":"","capDo":"khac","parentId":null,"blurb":"Cánh cửa bí ẩn mà chân thân Liễu Thần đã bước qua.","detail":"Theo lời Liễu Thần, không ai bước qua cánh cửa Nguyên Thủy có thể trở lại. Chân thân của người vì thế có khả năng không bao giờ tái hiện trên thế gian, khiến Thạch Hạo quyết tâm tới thế giới bên kia tìm kiếm.","theLucLienQuan":[],"nguon":["@c1014"]},{"id":"the-gioi-lieu-than-tung-sinh-song","name":"Thế giới Liễu Thần từng sinh sống","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Quê cũ của Liễu Thần, nay đã bị thiêu trụi và không còn tồn tại như trước.","detail":"Đây là thế giới Liễu Thần từng quen thuộc và sinh sống. Vùng đất cũ đã bị thiêu trụi, còn toàn bộ những người nó quen biết đều đã chết.","theLucLienQuan":[],"nguon":["@c1016"]},{"id":"the-gioi-phia-dich-thu","name":"Thế giới phía địch thủ","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Thế giới xa lạ mà Liễu Thần muốn tìm tới để hoàn thành tâm nguyện.","detail":"Nơi này khác hẳn Ba ngàn châu và nằm trên con đường vượt qua cánh cửa Nguyên Thủy. Muốn tìm đường tới đó, Thạch Hạo trước hết phải đến Biên Hoang rồi tìm cách chủ động đánh sang phía bên kia.","theLucLienQuan":[],"nguon":["@c1016"]},{"id":"ac-ma-dao","name":"Ác Ma đảo","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Nơi gắn với huyết dịch Ma tôn đang tẩm bổ Đại ma thần.","detail":"Huyết dịch Ma tôn có nguồn gốc từ Ác Ma đảo và tiếp tục giúp thể phách Đại ma thần trở nên mạnh mẽ hơn.","theLucLienQuan":[],"nguon":["@c1017"]},{"id":"hoa-tang-lam","name":"Hỏa Tang lâm","cn":"","aliases":["Rừng Hỏa Tang"],"capDo":"khac","parentId":"hoa-chau","blurb":"Vùng Hỏa Tang thụ tại Hỏa châu, gắn với một cố nhân trong quá khứ của Thạch Hạo.","detail":"Thạch Hạo tới nơi này sau khi rời tổ phụ. Hỏa Tang vẫn như xưa, nhưng hắn chưa biết cố nhân còn ở đó hay không.","theLucLienQuan":[],"nguon":["@c1017"]},{"id":"di-dia-tieu-vien-cua-hoa-linh-nhi","name":"Di địa tiểu viện của Hỏa Linh Nhi","cn":"","capDo":"khac","parentId":"hoa-tang-lam","blurb":"Phế tích nơi ở cũ của Hỏa Linh Nhi trong Hỏa Tang lâm. Nhà tranh và sân nhỏ đã bị thiêu hủy, chỉ còn đất cháy đen cùng dấu vết của một trận chiến.","detail":"Tại di địa còn một mảnh cốt thuẫn vỡ, máu khô và hai cây Hỏa Tang do Thạch Hạo cùng Hỏa Linh Nhi từng trồng. Thạch Hạo tìm kiếm nơi này suốt một ngày một đêm nhưng không phát hiện thêm manh mối về tung tích của nàng.","theLucLienQuan":["Hỏa tộc thượng giới"],"nguon":["@c1018"]},{"id":"quoc-tho-thien-nhan-toc","name":"Quốc thổ Thiên Nhân tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Lãnh thổ rộng lớn của Thiên Nhân tộc, gồm núi non, bình nguyên và nhiều thành trì.","detail":"Khu vực này có linh khí dày đặc và là nơi đông đảo thành viên Thiên Nhân tộc sinh sống. Thạch Hạo cùng Hỏa Linh Nhi đi xuyên qua quốc thổ trước khi tiến vào tổ địa được cổ trận bảo vệ.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c1021"]},{"id":"ngo-dong-linh","name":"Ngô Đồng lĩnh","cn":"","capDo":"khac","parentId":"ba-ngan-chau","blurb":"Một danh thắng được cho là nơi Phượng hoàng ẩn cư.","detail":"Thạch Hạo và Hỏa Linh Nhi ghé qua Ngô Đồng lĩnh trong hành trình du ngoạn, quan sát hồng trần và luyện tâm.","theLucLienQuan":[],"nguon":["@c1025"]},{"id":"dam-lanh-chan-long","name":"Đầm lạnh Chân Long","cn":"","capDo":"khac","parentId":"ba-ngan-chau","blurb":"Đầm lạnh nổi danh vì được cho là nơi Chân Long chiếm giữ.","detail":"Thạch Hạo và Hỏa Linh Nhi ghé qua nơi này trong chuyến du ngoạn kéo dài khoảng một tháng nhằm luyện tâm và ổn định trạng thái Thánh tế.","theLucLienQuan":[],"nguon":["@c1025"]},{"id":"thanh-thanh","name":"Thanh thành","cn":"","capDo":"thanh","parentId":"thanh-chau","blurb":"Một thành trì tu sĩ phồn hoa thuộc Thanh châu, nơi phàm nhân rất ít và cường giả tụ tập đông đảo.","detail":"Linh dược và thịt hung thú được bán phổ biến trong thành, còn nhiều cường giả tới đây luyện tâm giữa hồng trần. Cuộc tụ hội nhằm truyền tin và thu hút nhóm khách vực ngoại được tổ chức trên tàn thể Sơn thần ở trung tâm thành.","theLucLienQuan":[],"nguon":["@c1026"]},{"id":"tan-the-son-than-o-thanh-thanh","name":"Tàn thể Sơn thần ở Thanh thành","cn":"","capDo":"khac","parentId":"thanh-thanh","blurb":"Ngọn núi đá cháy đen cao hàng nghìn trượng nằm giữa Thanh thành, tương truyền là tàn thể của một Sơn thần mạnh hơn Giáo chủ.","detail":"Sơn thần bị thiên kiếp ép rời khỏi bản thể rồi chém chết nguyên thần. Tàn thể vẫn lưu lại khí tức Tiên đạo và pháp tắc cấm phi hành, khiến người dưới Chân Thần cảnh không thể leo lên; trên núi có quán rượu, quán trà và các lầu dành cho tu sĩ mạnh mẽ.","theLucLienQuan":[],"nguon":["@c1026"]},{"id":"cuu-thien-thap-dia","name":"Cửu Thiên thập Địa","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Cấu trúc thế giới rộng lớn bao gồm cửu Thiên và thập Địa, trong đó ba ngàn châu chỉ là một khu vực.","detail":"Tin tức về Cửu Thiên thập Địa gây chấn động các giáo tại ba ngàn châu và khiến nhiều tu sĩ muốn vượt giới thám hiểm.","theLucLienQuan":["Liên minh Cửu Thiên Thập Địa"],"nguon":["@c1026","@c1031","@c1061","@c1092"]},{"id":"khu-tao-hoa-tien-co","name":"Khu tạo hóa Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một khu vực tạo hóa trong Tiên cổ từng thu hút khoảng một trăm nhân tài hàng đầu tiến vào.","detail":"Nơi này có Ngọc thạch thư quý hiếm. Hiểu Nguyệt tiên tử từng tiến vào nhưng không đoạt được vật phẩm truyền thừa này.","theLucLienQuan":[],"nguon":["@c1026"]},{"id":"ngon-nui-gay-mau-den","name":"Ngọn núi gãy màu đen","cn":"","capDo":"khac","parentId":"thanh-thanh","blurb":"Một ngọn núi gãy màu đen nằm trong Thanh thành, gần nơi diễn ra cuộc tụ hội.","detail":"Khu vực quanh ngọn núi có khả năng quấy nhiễu vật thể phi hành, khiến chiến xa thần đồng năm màu của Viên Thiên lắc lư trước khi hạ xuống.","theLucLienQuan":[],"nguon":["@c1027"]},{"id":"ky-lan-linh","name":"Kỳ Lân lĩnh","cn":"","capDo":"vuc","parentId":"ba-ngan-chau","blurb":"Dãy núi từng có Kỳ Lân sinh sống và lưu lại dấu vết của sinh linh thuộc hàng Thập Hung.","detail":"Kỳ Lân lĩnh là nơi Ninh Xuyên bế quan và cũng là địa điểm được chọn cho cuộc quyết chiến giữa hắn với Lâm Thiên. Vùng núi còn lưu truyền chuyện một con Kỳ Lân trắng từng xuất hiện.","theLucLienQuan":[],"nguon":["@c1030"]},{"id":"noi-cu-tru-cua-gia-toc-ninh-xuyen","name":"Nơi cư trú của gia tộc Ninh Xuyên","cn":"","capDo":"khac","parentId":"ba-ngan-chau","blurb":"Nơi ở của gia tộc Ninh Xuyên nằm trong cùng đại châu với Kỳ Lân lĩnh.","detail":"Địa điểm này cách Kỳ Lân lĩnh không quá xa. Gia tộc Ninh Xuyên được mô tả là rất mạnh và từng đón nhiều đại giáo tới tranh nhau thu nhận hắn sau dị tượng lúc chào đời.","theLucLienQuan":["Yêu Long đạo môn","Hỏa Vân động","La Phù chân cốc"],"nguon":["@c1030"]},{"id":"chien-truong-trong-hu-khong","name":"Chiến trường trong hư không","cn":"","capDo":"khac","parentId":"ky-lan-linh","blurb":"Không gian tách biệt nơi Lâm Thiên và Ninh Xuyên tiến hành cuộc quyết chiến.","detail":"Hai người chuyển vào chiến trường trong hư không để phân thắng bại mà không cho người quan chiến nhìn rõ toàn bộ bảo thuật và thần thông. Khi trở lại, Lâm Thiên bị thương nặng hơn Ninh Xuyên.","theLucLienQuan":[],"nguon":["@c1030"]},{"id":"ba-ngan-dao-chau","name":"Ba ngàn đạo châu","cn":"","capDo":"chau","parentId":null,"blurb":"Khu vực xuất thân của Thạch Hạo và Ninh Xuyên, từng bị nhóm khách vực ngoại cho rằng đã sa sút.","detail":"Thạch Hạo và Ninh Xuyên chứng minh ba ngàn đạo châu vẫn có nhân vật xuất sắc khi cùng đạt tiêu chuẩn rời nơi này để gia nhập Thư viện Thiên Thần.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1031"]},{"id":"doan-nhai-tai-trung-chau","name":"Đoạn nhai tại Trung châu","cn":"","capDo":"khac","parentId":"trung-chau","blurb":"Nơi ba đại nhân vật chờ đoàn người do các sứ giả Thư viện Thiên Thần đưa tới.","detail":"Tại đoạn nhai này, Thạch Hạo và Ninh Xuyên gặp ba người đàn ông trung niên được khí hỗn độn cùng khí tức Tiên đạo bao phủ. Họ công bố thử thách Minh ước Thái cổ và hành trình tới một tòa cổ thành.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1031"]},{"id":"toa-co-thanh-lien-quan-minh-uoc-thai-co","name":"Tòa cổ thành liên quan Minh ước Thái cổ","cn":"","capDo":"thanh","parentId":null,"blurb":"Một tòa cổ thành chưa rõ tên, là đích đến trong thử thách đầu tiên dành cho những người được Thư viện Thiên Thần tuyển chọn.","detail":"Thạch Hạo và những người đồng hành phải tìm hiểu Minh ước Thái cổ rồi tới tòa thành này. Chỉ người hoàn thành thử thách mới có cơ hội tiến vào thư viện vô thượng.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1031"]},{"id":"cam-khu-vo-ngan","name":"Cấm khu vô ngần","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng cấm rộng lớn nằm ngoài ba ngàn đạo châu, chứa những vật chất dị thường có thể giết cả Giáo chủ và chí cường giả.","detail":"Cấm khu vô ngần rộng đến mức ba ngàn đạo châu được cho là chưa bằng một phần mười. Một con đường cổ tương đối an toàn dẫn xuyên qua nơi này tới tòa thành dùng làm đích tuyển chọn của thư viện Thiên Thần.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1032"]},{"id":"toa-co-thanh-sau-trong-cam-khu","name":"Tòa cổ thành sâu trong Cấm khu","cn":"","capDo":"thanh","parentId":"cam-khu-vo-ngan","blurb":"Tòa thành nằm ở nơi sâu trong Cấm khu, được chọn làm đích đến của cuộc tuyển chọn.","detail":"Người trẻ tuổi vượt qua con đường cổ và tới được tòa thành sẽ có tư cách rời giới hiện tại để tiến vào thư viện Thiên Thần.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1032"]},{"id":"con-duong-co-trong-cam-khu","name":"Con đường cổ trong Cấm khu","cn":"","capDo":"khac","parentId":"cam-khu-vo-ngan","blurb":"Con đường cổ hoang vắng dẫn tới tòa thành nằm sâu trong Cấm khu.","detail":"Dù vẫn là một hành trình cửu tử nhất sinh, con đường này được ba vị trung niên đánh giá là lối tương đối an toàn để dùng cho cuộc tuyển chọn nhân kiệt.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1032"]},{"id":"thang-chau","name":"Thặng châu","cn":"","capDo":"chau","parentId":"ba-ngan-chau","blurb":"Một châu có vùng biên giới tiếp giáp Cấm khu thuộc khu không người.","detail":"Biên giới Thặng châu được các ngọn núi khổng lồ ngăn cách với Cấm khu và là nơi ba đại chí tôn vực ngoại tập hợp đoàn người dự tuyển.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1035"]},{"id":"co-thanh-khao-nghiem","name":"Cổ thành khảo nghiệm","cn":"","capDo":"thanh","parentId":"cam-khu-vo-ngan","blurb":"Đích đến nằm sâu trong Cấm khu dành cho những người tham gia kỳ tuyển chọn.","detail":"Người dự tuyển tìm được cổ thành sẽ được xem là vượt qua cửa ải và có tư cách gia nhập thư viện Thiên Thần.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1035"]},{"id":"khu-vuc-dai-tinh-mau-lam","name":"Khu vực đại tinh màu lam","cn":"","capDo":"khac","parentId":"cam-khu-vo-ngan","blurb":"Khu vực trong Cấm khu được bao phủ bởi hàng vạn đại tinh màu lam đã qua luyện hóa.","detail":"Hai bên con đường có tinh tú vỡ rơi xuống, còn tại trung tâm là tàn trận phát kiếm khí vô hình chuyên chém nguyên hồn. Thanh Tiên từng bị giam cầm tại đây.","theLucLienQuan":[],"nguon":["@c1037"]},{"id":"tu-truc-lam","name":"Tử Trúc lâm","cn":"","capDo":"khac","parentId":"cam-khu-vo-ngan","blurb":"Rừng trúc tím phủ sương trắng mà Thạch Hạo tới sau năm ngày tiếp tục hành trình.","detail":"Khi Thạch Hạo tiến vào rừng, thiên địa biến đổi và mở ra một thế giới riêng tràn ngập khí tượng Tiên cổ.","theLucLienQuan":[],"nguon":["@c1037"]},{"id":"the-gioi-sau-tu-truc-lam","name":"Thế giới sau Tử Trúc lâm","cn":"","capDo":"gioi-nho","parentId":"tu-truc-lam","blurb":"Tiểu thiên địa tràn ngập tiên vụ, linh sơn, cổ dược, tiên cầm và thụy thú.","detail":"Nơi đây tồn tại những sinh linh chân thật vốn được cho là đã biến mất từ kỷ nguyên trước. Cư dân Tiên phủ không biết ba ngàn đạo châu, khiến Thạch Hạo nghi ngờ mình đang chứng kiến Tiên cổ tái hiện.","theLucLienQuan":["Tiên phủ"],"nguon":["@c1037"]},{"id":"nam-hai-tu-truc-lam","name":"Nam Hải Tử Trúc lâm","cn":"","capDo":"khac","parentId":"bien-xanh-nam-hai","blurb":"Phủ đệ của một vị tiền bối đại năng và là địa điểm tổ chức thịnh hội Chân Tiên.","detail":"Tử Trúc lâm nằm giữa Nam Hải, gồm những cây trúc tím cao như núi, cắm rễ dưới đáy biển xanh và tỏa hơi tím. Người dự hội phải xuyên qua khu rừng này để tới đạo thổ nằm sâu bên trong.","theLucLienQuan":[],"nguon":["@c1038"]},{"id":"bien-xanh-nam-hai","name":"Biển xanh Nam Hải","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển vô ngần bao quanh Nam Hải Tử Trúc lâm.","detail":"Biển xanh tràn ngập sương trắng và khí tức Tiên đạo. Bạch Giao quân vương rẽ sóng tại đây, còn nhiều cường giả vượt biển để tới thịnh hội.","theLucLienQuan":[],"nguon":["@c1038"]},{"id":"dao-tho-giua-nam-hai","name":"Đạo thổ giữa Nam Hải","cn":"","capDo":"khac","parentId":"nam-hai-tu-truc-lam","blurb":"Lục địa thanh khiết nằm sâu sau Tử Trúc lâm, là nơi khách dự thịnh hội tụ tập.","detail":"Đạo thổ có hoa thơm, cỏ lạ, chim hót và một Tiên đài nửa lơ lửng trong không trung. Hoa sen vàng cắm rễ trong hư không, thần lộc dâng trái cây và vượn trắng rót rượu cho khách.","theLucLienQuan":[],"nguon":["@c1038"]},{"id":"dong-phu-tien-co","name":"Động phủ Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Di tích và chiến trường nổi danh của Tiên cổ, nơi trở thành điểm nối để kỳ cảnh quá khứ hiện ra trước người đương đại.","detail":"Thạch Hạo bước vào Động phủ Tiên cổ và được kéo vào một không gian đặc biệt do các đại nhân vật thời xưa tạo ra. Tại đây, hắn có thể giao lưu với người Tiên cổ và chứng kiến ngày cuối của thời đại ấy nhưng không thể thay đổi kết cục.","theLucLienQuan":["Tiên phủ"],"nguon":["@c1040"]},{"id":"tien-phu-phu-de","name":"Tiên phủ","cn":"","capDo":"khac","parentId":"dong-phu-tien-co","blurb":"Phủ đệ Tiên gia từng thánh khiết và an lành, nơi Thạch Hạo sống cùng các chí tôn trẻ tuổi trong kỳ cảnh.","detail":"Thạch Hạo trải qua vài tháng giao lưu với những người Tiên cổ tại đây. Khi cuộc xâm lấn bắt đầu, con mắt dữ tợn, xương lớn, sương xám, vảy đỏ và dây leo tràn tới khiến Tiên phủ nhanh chóng biến thành chiến trường phủ đầy máu.","theLucLienQuan":["Tiên phủ"],"nguon":["@c1040"]},{"id":"day-mo-co-ri-mau","name":"Dãy mộ cổ rỉ máu","cn":"","capDo":"khac","parentId":"cam-khu-vo-ngan","blurb":"Một dãy mộ cổ có thể rung chuyển, dịch chuyển và rỉ máu trong Cấm khu.","detail":"Những dãy núi tại đây thực chất là các ngôi mộ cổ có ý trấn áp Thạch Hạo. Sự dịch chuyển của chúng làm lộ ra hàng ngàn thi thể thiên tài trẻ tuổi đến từ ba ngàn châu.","theLucLienQuan":[],"nguon":["@c1041"]},{"id":"noi-sau-cam-khu","name":"Nơi sâu Cấm khu","cn":"","capDo":"vuc","parentId":"cam-khu-vo-ngan","blurb":"Khu vực sâu trong Cấm khu có nhiều di tích và cổ trận thuộc kỷ nguyên trước.","detail":"Thạch Hạo gặp một toán Thiên Thần thiện chiến tại đây. Những đạo phù cổ bảo vệ núi sông khỏi dư chấn chiến đấu, còn đôi mắt đỏ máu của đối phương khiến hắn liên tưởng tới kẻ địch trong mộng Tiên cổ.","theLucLienQuan":["Đội Mười Chín"],"nguon":["@c1042"]},{"id":"toa-thanh-lon-cuoi-chan-troi","name":"Tòa thành lớn cuối chân trời","cn":"","capDo":"thanh","parentId":"noi-sau-cam-khu","blurb":"Một thành trì rộng lớn và hùng vĩ nằm ở cuối chân trời trong Cấm khu.","detail":"Thạch Hạo nhìn thấy tòa thành sau nhiều ngày vượt qua vô số núi sông. Quy mô của nó khiến hắn liên tưởng tới thủ phủ của một vị hoàng đế.","theLucLienQuan":[],"nguon":["@c1042"]},{"id":"binh-nguyen-gan-bien-hoang","name":"Bình nguyên gần Biên hoang","cn":"","capDo":"khac","parentId":"bien-hoang","blurb":"Bình nguyên khô cằn gần Biên hoang, nơi một thành trì nguy nga được dựng lên.","detail":"Khu vực không có núi chắn ngang, chỉ rải rác những cổ mộc cao tới mấy trăm trượng. Thành trì gần Biên hoang nổi bật giữa vùng đất rộng lớn này.","theLucLienQuan":[],"nguon":["@c1043"]},{"id":"thanh-tri-cua-hau-due-cao-thu-minh-uoc-thai-co","name":"Thành trì của hậu duệ cao thủ Minh ước Thái cổ","cn":"","capDo":"thanh","parentId":"binh-nguyen-gan-bien-hoang","blurb":"Thành trì gần Biên hoang hình thành từ nơi sinh sống của đệ tử và hậu duệ các cao thủ từng thực hiện Minh ước Thái cổ.","detail":"Thành trì có nhiều chủng tộc và cao thủ cùng sinh sống nhưng chưa phải cổ thành biên giới chân chính. Một số cao thủ trong thành đã bị khí thế từ Biên hoang ăn mòn và mê hoặc tâm trí.","theLucLienQuan":["Thiên Thần"],"nguon":["@c1043"]},{"id":"co-thanh-bien-gioi","name":"Cổ thành biên giới","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Tòa cổ thành chân chính trấn giữ khu vực biên giới.","detail":"Theo lời Ma nữ, cổ thành này lớn hơn thành trì của hậu duệ cao thủ Minh ước Thái cổ gấp trăm lần và mang khí thế như một tòa thành của Thiên đế.","theLucLienQuan":[],"nguon":["@c1043"]},{"id":"de-thanh","name":"Đế thành","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Tòa thành tại Biên hoang mà Thạch Hạo và Ma nữ đang tìm kiếm.","detail":"Đế thành là mục tiêu chính khiến Thạch Hạo và Ma nữ từ bỏ việc săn Kỳ lân, rời thành cổ và tiếp tục tiến sâu qua Cấm khu về phía Biên hoang.","theLucLienQuan":[],"nguon":["@c1044","@c1063"]},{"id":"thanh-thien-de","name":"Thành Thiên đế","cn":"","capDo":"thanh","parentId":null,"blurb":"Tòa thành được gọi là Thiên đế, điểm đến kế tiếp của Thạch Hạo và Ma nữ.","detail":"Sau khi phá hủy Huyết Tế Đàn và cắt đứt con đường vượt giới, Thạch Hạo cùng Ma nữ tiếp tục tiến quân về tòa thành này.","theLucLienQuan":[],"nguon":["@c1045"]},{"id":"bien-co-chien-truong","name":"Biển cổ chiến trường","cn":"","capDo":"khac","parentId":"cam-khu-vo-ngan","blurb":"Vùng biển mênh mông chắn đường tới Đế thành, lưu giữ dấu ấn kèn lệnh của cuộc chiến hơn một kỷ nguyên trước và phát ra kiếm khí thật đủ giết Giáo chủ.","detail":"Chiến trường cổ đại trong Cấm khu, nơi ngay cả Giáo chủ tiến vào cũng khó sống sót. Dấu ấn kèn lệnh ốc biển tái hiện cảnh trời đất nổ tung, đồng thời kiếm khí thật sự bùng phát có thể cắt đứt thiên địa và kéo thiên thạch từ vực ngoại rơi xuống. Thạch Hạo và Ma nữ phải mất hơn nửa tháng đi vòng mới vượt qua. Sinh linh bản địa tại thành trì gần đó xác nhận đây là chiến trường cổ cực kỳ nguy hiểm.","theLucLienQuan":[],"nguon":["@c1046"]},{"id":"co-thanh-ven-duong","name":"Cổ thành ven đường","cn":"","capDo":"thanh","parentId":"cam-khu-vo-ngan","blurb":"Thành trì trong Cấm khu nơi Thạch Hạo và Ma nữ hỏi đường và xác nhận phương hướng tới Đế thành.","detail":"Một trong số ít thành trì tồn tại trong Cấm khu, nơi sinh linh bản địa xác nhận vùng biển gần đó là chiến trường cổ và giúp hai người kiểm tra lại hướng đi tới Đế thành.","theLucLienQuan":[],"nguon":["@c1046"]},{"id":"vung-bien-de-cot","name":"Vùng biển Đế cốt","cn":"","capDo":"khac","parentId":"bien-dung-nham","blurb":"Phần biển dung nham mai táng nhiều nhân vật được gọi là Đế trên con đường tu hành, tàn cốt sau vô tận năm tháng vẫn còn tinh lực đủ xuyên trời đánh rơi sao.","detail":"Khu vực được mỏm đá khắc chữ cổ xác nhận tên gọi. Nơi chôn cất các Đại Đế đã chết trận trong đại chiến cổ đại, nhiều bộ tộc chôn người mạnh nhất cùng một chỗ. Dưới đáy biển có nhiều bộ hài cốt, trong đó một bộ xương ngồi xếp bằng sáng như mặt trời, tinh lực còn sót trong Thiên Linh cái phóng ra ánh đỏ xuyên thủng trời cao và đánh rơi sao trời. Ma nữ kết luận tất cả Đại Đế nơi đây đều chết trận, cho thấy quy mô tàn khốc vượt mức tưởng tượng của trận chiến năm xưa.","theLucLienQuan":[],"nguon":["@c1046"]},{"id":"phuong-hoang-son","name":"Phượng Hoàng Sơn","cn":"","capDo":"khac","parentId":"bien-dung-nham","blurb":"Ngọn núi khổng lồ mọc lên từ đáy biển dung nham, cao gần những ngôi sao vực ngoại.","detail":"Đỉnh núi rộng như đại lục và mang ba chữ cổ Phượng Hoàng Sơn. Trên đỉnh có một tòa cổ thành cùng nhiều cây ngô đồng đã chết khô nhưng không mục nát, gợi dấu tích về nơi Chân Hoàng từng sinh sống.","theLucLienQuan":[],"nguon":["@c1047"]},{"id":"co-thanh-chan-hoang","name":"Cổ thành Chân Hoàng","cn":"","capDo":"thanh","parentId":"phuong-hoang-son","blurb":"Tòa cổ thành tĩnh mịch nằm trên đỉnh Phượng Hoàng Sơn, được bao phủ bởi những trận pháp mạnh mẽ.","detail":"Cổ thành có nhiều cây ngô đồng chết khô, đại trận giam giữ người xâm nhập và trận pháp giúp các kiến trúc tự phục hồi. Những sinh linh kỳ quái như quái vật một chân và ông lão xác ướp xuất hiện rồi biến mất trong thành.","theLucLienQuan":[],"nguon":["@c1047"]},{"id":"dong-phu-hon-don","name":"Động phủ hỗn độn","cn":"","capDo":"khac","parentId":"co-thanh-chan-hoang","blurb":"Động phủ tràn ngập hỗn độn khí và tiên quang, được nối với cổ thành Chân Hoàng bằng đại trận truyền tống.","detail":"Thạch Hạo và Ma nữ được truyền tống tới đây sau khoảng một tháng rưỡi thăm dò cổ thành. Bên trong động phủ có một quả trứng khổng lồ tỏa sinh cơ và tinh khí sinh mệnh mạnh mẽ.","theLucLienQuan":[],"nguon":["@c1047"]},{"id":"de-thanh-trong-cam-khu","name":"Đế thành trong Cấm khu","cn":"","capDo":"thanh","parentId":"cam-khu-vo-ngan","blurb":"Một thành trì khổng lồ nối liền trời đất, được luyện chế từ các ngôi sao và thiên thạch.","detail":"Đế thành có những đại tinh chuyển động xung quanh và được trận pháp vô thượng bảo vệ. Chỉ người đã ký Minh ước Thái cổ mới được vào, nhưng lúc Thạch Hạo và Ma nữ tới nơi, thành trì không có hồi đáp hay dao động sinh mệnh, tựa như một tòa thành chết.","theLucLienQuan":[],"nguon":["@c1049"]},{"id":"thanh-co-do-bay-vi-vuong-tran-thu","name":"Thành cổ do bảy vị Vương trấn thủ","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Thành cổ tại Biên hoang từng được Thạch Hạo nhìn thấy qua chiếc thuyền đen nhuốm máu.","detail":"Thành trì này do bảy vị Vương cùng nhóm người mang tội huyết tử thủ. Thạch Hạo xác định đây là một nơi khác với Đế thành trong Cấm khu, có quy mô nhỏ và kém hùng vĩ hơn.","theLucLienQuan":["Nhóm người mang tội huyết"],"nguon":["@c1049"]},{"id":"khu-pho-cho-ngoai-de-thanh","name":"Khu phố chợ ngoài Đế thành","cn":"","capDo":"khac","parentId":"de-thanh-trong-cam-khu","blurb":"Cụm thành nhỏ và phố chợ nằm quanh Đế thành, do hậu duệ của các cao thủ tuyệt đại phát triển.","detail":"Khu vực này có nhiều sinh linh sinh sống và là nơi những người sống sót sau hành trình nguy hiểm tụ tập. Thạch Hạo và Ma nữ gặp lại các thiên tài ba ngàn châu tại đây, đồng thời chạm mặt nhóm tu sĩ Cửu Thiên.","theLucLienQuan":["Tu sĩ Cửu Thiên"],"nguon":["@c1049"]},{"id":"toa-thanh-lon-nhat-trong-khu-pho-cho","name":"Tòa thành lớn nhất trong khu phố chợ","cn":"","capDo":"thanh","parentId":"khu-pho-cho-ngoai-de-thanh","blurb":"Tòa thành lớn nhất trong cụm phố chợ ngoài Đế thành, nơi những người vượt ải tụ tập chờ đợi.","detail":"Thập Quan vương, Trích tiên, Ninh Xuyên, Nguyệt Thiền và những tu sĩ trẻ tuổi khác đã tập trung tại đây. Số người sống sót ít hơn rất nhiều so với mười vạn người xuất phát ban đầu.","theLucLienQuan":["Tu sĩ Cửu Thiên"],"nguon":["@c1049"]},{"id":"co-thanh-tren-duong-toi-thu-vien-thien-than","name":"Cổ thành trên đường tới thư viện Thiên Thần","cn":"","capDo":"thanh","parentId":"cuu-thien-thap-dia","blurb":"Nơi các thiên tài từ ba ngàn đạo châu và Vô Lượng Thiên tụ họp trước khi xác định danh sách vào thư viện Thiên Thần.","detail":"Bên ngoài cổ thành có nhiều nhóm thiên tài chia thành các liên minh trên những tảng đá. Trong thành có cao thủ giữ trật tự và việc quyết đấu trước cửa thành bị ngăn cấm.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1050"]},{"id":"vo-luong-thien","name":"Vô Lượng Thiên","cn":"","capDo":"gioi-dien","parentId":"cuu-thien-thap-dia","blurb":"Một Thiên mạnh thuộc Cửu Thiên thập Địa, được mô tả là thánh thổ thích hợp cho việc tu luyện.","detail":"Nhóm thiên tài đến từ Vô Lượng Thiên cho rằng thư viện Thiên Thần sẽ được bố trí tại đây và công khai mời Ma nữ tới tu luyện.","theLucLienQuan":["Thư viện Thiên Thần"],"nguon":["@c1050"]},{"id":"co-thanh-co-bach-ky-lan-xuat-hien","name":"Cổ thành có Bạch Kỳ Lân xuất hiện","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Một tòa cổ thành chưa rõ tên tại biên hoang, gần nơi Bạch Kỳ Lân ấu thú được cho là đang ẩn náu.","detail":"Ba vị Chí Tôn chỉ dẫn các thiên tài đến khu vực gần tòa cổ thành này để tìm Bạch Kỳ Lân. Tin Thiên Thần thư viện sẽ toàn lực bồi dưỡng người mang được ấu thú trở về khiến nơi đây trở thành mục tiêu của các đội dự tuyển.","theLucLienQuan":["Thiên Thần thư viện"],"nguon":["@c1051"]},{"id":"nguyen-thuy-dai-hoang","name":"Nguyên thủy Đại Hoang","cn":"","capDo":"vuc","parentId":"khu-khong-nguoi","blurb":"Hiểm địa nằm ngoài con đường cổ an toàn, nơi Ninh Xuyên dẫn đầu cuộc tìm kiếm Bạch Kỳ Lân.","detail":"Khu vực này có những anh linh tử trận mạnh hơn giáo chủ, một thi hài mục nát mang cánh đen bị nghi thuộc Chí Tôn và vùng núi rừng chứa các vũng máu cổ. Bạch Kỳ Lân cùng thiếu nữ bí ẩn xuất hiện tại một ngọn núi trong khu vực.","theLucLienQuan":[],"nguon":["@c1052"]},{"id":"nui-rung-vung-mau","name":"Núi rừng vũng máu","cn":"","capDo":"khac","parentId":"nguyen-thuy-dai-hoang","blurb":"Khu rừng tĩnh lặng chứa nhiều vũng máu cổ không khô và hài cốt rải rác.","detail":"Một vũng máu nhỏ tại đây có thể kéo xuống và hòa tan tức khắc một thiên tài đã tu thành tiên khí. Trong khu vực còn có ngọn núi cất giấu Bạch Kỳ Lân cùng thiếu nữ mang Tiên Đạo khí tức.","theLucLienQuan":[],"nguon":["@c1052"]},{"id":"bao-dia-phong-an-bach-ky-lan","name":"Bảo địa phong ấn Bạch Kỳ Lân","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực núi non từng phong ấn Bạch Kỳ Lân non, mang tiên đạo khí tức và hỗn độn khí.","detail":"Sau khi ngọn núi phong ấn sụp đổ, nơi này trở thành điểm tập trung của các chí tôn trẻ tuổi tranh đoạt Bạch Kỳ Lân. Sương trắng và hỗn độn khí bao phủ khu vực, trong khi những vũng máu trên mặt đất có thể khiến người bước vào hóa thành máu mủ.","theLucLienQuan":[],"nguon":["@c1053"]},{"id":"tuong-thanh-phia-xa","name":"Tường thành phía xa","cn":"","capDo":"thanh","parentId":"chien-truong-co","blurb":"Một bức tường thành khác nằm ở nơi xa vô tận phía trước chiến trường cổ.","detail":"Khoảng cách tới bức tường xa đến mức đoàn người không thể trực tiếp nhìn thấy và phải quan sát cảnh tượng qua cốt kính.","theLucLienQuan":[],"nguon":["@c1056"]},{"id":"bien-quan-ngoai-chien-truong-co","name":"Biên quan ngoài chiến trường cổ","cn":"","capDo":"khac","parentId":"chien-truong-co","blurb":"Khu vực nằm ngoài chiến trường cổ, có thể bị tiếp cận qua những khe lớn kỳ dị.","detail":"Tam đại Chí Cường giả cảnh báo các thiên tài không bước nhầm vào khe lớn dẫn khỏi biên quan, bởi phía bên kia là thế giới của kẻ địch.","theLucLienQuan":[],"nguon":["@c1056"]},{"id":"loi-di-mau-den","name":"Lối đi màu đen","cn":"","capDo":"khac","parentId":"chien-truong-co","blurb":"Con đường kỳ dị xuất hiện dưới chân Thạch Hạo khi thời gian quanh hắn như ngưng đọng.","detail":"Thạch Hạo đặt chân lên lối đi mà không kịp rút lại, lập tức bị đưa khỏi chiến trường cổ tới một vùng đất tối tăm khác.","theLucLienQuan":[],"nguon":["@c1056"]},{"id":"khu-vuc-dat-dinh-than-bi","name":"Khu vực đặt đỉnh thần bí","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng đất tối tăm nơi Thạch Hạo nhìn thấy chân thân chiếc đỉnh ba chân hai tai nhuốm máu.","detail":"Nơi đây có tầm nhìn thấp, khói đen, núi sông không cây cỏ và vô số xương trắng. Chiếc đỉnh lưu chuyển mẫu khí, lơ lửng bất động giữa vùng đất này.","theLucLienQuan":[],"nguon":["@c1056"]},{"id":"chien-truong-toi-tam","name":"Chiến trường tối tăm","cn":"","capDo":"khac","parentId":null,"blurb":"Một chiến trường cô tịch với mặt đất cháy đen, xương khô dày đặc và khói đen bao phủ.","detail":"Thạch Hạo gặp chân thân của bảo đỉnh tại đây. Cuộc đối thoại giữa hắn và tiếng thần niệm trong đỉnh liên tục dẫn phát lôi kiếp, tiên khí cùng sự phản phệ dữ dội của quy tắc.","theLucLienQuan":[],"nguon":["@c1057"]},{"id":"tien-co-di-hac-uyen","name":"Tiên cổ di hắc uyên","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một hắc uyên thuộc di tích Tiên cổ, nằm dưới tế đàn tàn tạ.","detail":"Đây là nơi Thạch Hạo từng nhìn thấy bóng mờ hoặc dấu ấn hư không của bảo đỉnh và nhận được thông tin rằng nó đến để cầu viện. Ký ức về lần gặp này giúp hắn nhận ra chân thân bảo đỉnh khi nó xuất hiện.","theLucLienQuan":[],"nguon":["@c1057"]},{"id":"chien-truong-ky-di-gan-de-thanh","name":"Chiến trường kỳ dị gần Đế Thành","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường cháy đen gần Đế Thành, không có cây cỏ và phủ đầy xương khô.","detail":"Không gian này mang tử khí nặng nề, khắp nơi là xương khô của vô số anh kiệt đã chết từ những năm tháng xa xưa. Thạch Hạo ở đây khi cổ đỉnh chống lại Tiên Đạo lôi đình rồi xé hư không rời đi.","theLucLienQuan":[],"nguon":["@c1058"]},{"id":"the-gioi-phia-ben-kia","name":"Thế giới phía bên kia","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Vùng tịnh thổ nằm sau khe hư không do cổ đỉnh để lại, có quy tắc đại đạo khác thường và nhiều sinh vật mắt đỏ.","detail":"Nơi này có non xanh nước biếc, linh khí dồi dào và áp lực đại đạo mênh mông, trái ngược hoàn toàn với chiến trường đầy xương khô. Tử Vong Long Chủy Điểu cùng nhiều hung thú mắt đỏ sống tại đây đều không thể thuần phục và sẽ hóa thành bụi khi bị thương, khiến Thạch Hạo nghi ngờ đây là lãnh địa của kẻ địch.","theLucLienQuan":[],"nguon":["@c1058"]},{"id":"tien-co-di-dia","name":"Tiên Cổ di địa","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Di địa Tiên Cổ từng được nối thông khi ba ngàn đại đạo cánh hoa nở.","detail":"Tử Vong Long Chủy Điểu từng thuộc một chủng tộc hùng mạnh của kỷ nguyên trước, nhưng ngay tại di địa này cũng đã tuyệt diệt vì không thích ứng với biến hóa của quy tắc càn khôn đời sau.","theLucLienQuan":[],"nguon":["@c1058"]},{"id":"the-gioi-ben-kia-bien-hoang","name":"Thế giới bên kia biên hoang","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Một thế giới có quy tắc và trật tự thiên địa khác với nơi Thạch Hạo xuất phát. Nơi đây có dược thảo Tiên cổ, các sơn mạch chôn đầy hài cốt và nhiều thành trì của Nhân tộc lẫn dị tộc.","detail":"Thạch Hạo nghi mình đã thực sự vượt qua biên hoang để tới thế giới này, nhưng chưa có xác nhận tuyệt đối. Cư dân bản địa dùng chung một loại cổ ngữ và đưa ra cách lý giải đối nghịch về quyền sở hữu Cửu Thiên Thập Địa.","theLucLienQuan":["Cư dân các cổ thành bên kia biên hoang"],"nguon":["@c1059"]},{"id":"vung-nui-tim","name":"Vùng núi tím","cn":"","capDo":"khac","parentId":"the-gioi-ben-kia-bien-hoang","blurb":"Vùng núi có linh khí đặc biệt nồng đậm, linh tuyền có thể hóa thành Linh dịch và nhiều dược thảo Tiên cổ sinh trưởng.","detail":"Bên dưới những nơi có thánh dược là các xác ướp cổ. Dược liệu cắm rễ trên thi hài và liên tục hấp thu tinh khí để sinh trưởng.","theLucLienQuan":[],"nguon":["@c1059"]},{"id":"son-mach-hai-cot","name":"Sơn mạch hài cốt","cn":"","capDo":"khac","parentId":"the-gioi-ben-kia-bien-hoang","blurb":"Một vùng sơn mạch rộng lớn có vô số hài cốt sinh linh Tiên cổ chôn dưới lòng đất.","detail":"Thạch Hạo phá núi kiểm tra và phát hiện ngay cả những khu vực không có thánh dược cũng chứa dày đặc xương cốt của nhiều giống loài, từ người khổng lồ đến tử kim thử. Khu vực này do Tử Vong Long Chủy Điểu thống trị.","theLucLienQuan":[],"nguon":["@c1059"]},{"id":"co-thanh-trung-nhan-mau-den","name":"Cổ thành trùng nhân màu đen","cn":"","capDo":"thanh","parentId":"the-gioi-ben-kia-bien-hoang","blurb":"Một cổ thành xây bằng khoáng thạch đen, có khí thế như hung thú ngủ đông.","detail":"Thành trì do chủng tộc có thân dưới giống Giao Long, thân trên hình người và đôi cánh chim màu đen trấn giữ. Thạch Hạo không vào thành vì ngoại hình khác biệt có thể làm lộ thân phận.","theLucLienQuan":["Bộ tộc trùng nhân cánh đen"],"nguon":["@c1059"]},{"id":"cu-thanh-nhan-toc","name":"Cự thành Nhân tộc","cn":"","capDo":"thanh","parentId":"the-gioi-ben-kia-bien-hoang","blurb":"Một thành trì đông đúc của Nhân tộc tại thế giới bên kia biên hoang. Đây là nơi Thạch Hạo trà trộn nhiều ngày để tìm hiểu ngôn ngữ, phong tục và quan điểm của cư dân bản địa.","detail":"Sau khi đọc ký ức của hai người ngoài thành, Thạch Hạo thay y phục bản địa và vào thành mà không bị nghi ngờ. Tại đây, hắn nghe tuyên bố rằng Cửu Thiên Thập Địa vốn thuộc về cư dân nơi này nhưng đã bị đối phương xâm chiếm.","theLucLienQuan":["Cư dân các cổ thành bên kia biên hoang"],"nguon":["@c1059"]},{"id":"bat-hu-son","name":"Bất Hủ Sơn","cn":"","capDo":"khac","parentId":"the-gioi-ben-kia-bien-hoang","blurb":"Ngọn núi khổng lồ màu nâu đỏ ở thế giới bên kia Biên Hoang, mang uy áp khiến người tới gần khó thở. Sau khi sống lại, nơi đây xuất hiện nhiều tàn đồ và khắc đá liên quan đến Bất Hủ người.","detail":"Bất Hủ Sơn có màu nâu đỏ như từng bị máu nhuộm và tỏa ra uy áp khủng khiếp. Thạch Hạo tới đây sau khi nghe tin ngọn núi sống lại, rồi nhìn thấy các hình ảnh cổ mô tả những sinh vật vô thượng từng đạt tới trạng thái bất hủ.","theLucLienQuan":[],"nguon":["@c1060"]},{"id":"the-gioi-cua-bat-hu-gia","name":"Thế giới của bất hủ giả","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Một thiên địa khác được cho là nơi các bất hủ giả cư trú. Cổ lộ trên đỉnh Bất Hủ Sơn có thể đưa những người tu thành tiên khí tới nơi này.","detail":"Trong nhận thức của những người leo Bất Hủ Sơn, đây là một tịnh thổ có vô thượng sinh linh và cơ duyên được chỉ điểm. Thạch Hạo lại nghi ngờ nơi này thuộc về lực lượng từng đối địch với Cửu Thiên Thập Địa và đang tuyển chọn thiên tài bản địa.","theLucLienQuan":[],"nguon":["@c1061"]},{"id":"co-lo-mau-vang","name":"Cổ lộ màu vàng","cn":"","capDo":"khac","parentId":"bat-hu-son","blurb":"Con đường màu vàng hiện ra trong hư không trên đỉnh Bất Hủ Sơn, dẫn về phía một thế giới khác.","detail":"Thiếu nữ và nam tử giáp lam bước lên cổ lộ này để rời đi. Thạch Hạo chủ động từ chối con đường, xuống núi và trở về thế giới của mình.","theLucLienQuan":[],"nguon":["@c1062"]},{"id":"the-gioi-cua-thach-hao","name":"Thế giới của Thạch Hạo","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Thế giới mà Thạch Hạo xem là quê hương và quyết định quay về sau khi rời Bất Hủ Sơn.","detail":"Sau khi từ chối cổ lộ màu vàng, Thạch Hạo xé hư không rời khỏi khu vực vì muốn trở lại thế giới của mình và đề phòng sinh linh phía bên kia truy sát.","theLucLienQuan":[],"nguon":["@c1062"]},{"id":"bat-huu-son","name":"Bất Hủ sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Trung tâm tại dị giới nơi thần niệm của Bất Hủ giả quét tới và kim sắc pháp chỉ giáng xuống.","detail":"Uy thế phát ra từ Bất Hủ sơn khiến sinh linh dị giới chấn động. Giáo chủ, cao thủ và nhân vật thủ lĩnh từ các đại thánh địa đồng loạt đến đây yết kiến và tiếp nhận tin tiên chiến sắp mở.","theLucLienQuan":["Các đại thánh địa dị giới"],"nguon":["@c1063"]},{"id":"khong-gian-u-am-cua-bao-dinh","name":"Không gian u ám của bảo đỉnh","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Vùng không gian trung chuyển được thần bí bảo đỉnh dùng để đưa Thạch Hạo rời dị giới.","detail":"Thạch Hạo được dẫn vào nơi này sau khi thông đạo tại dãy núi mở ra. Bảo đỉnh xóa tiết điểm cùng dấu vết phía sau rồi phá hư không, đưa hắn trở lại ngoại thành Đế Thành.","theLucLienQuan":[],"nguon":["@c1063"]},{"id":"hach-tam-de-thanh","name":"Hạch tâm Đế Thành","cn":"","capDo":"thanh","parentId":"de-thanh","blurb":"Cự thành nằm sâu bên trong Đế Thành, là phần hạch tâm chân chính. Thạch Hạo được đưa tới đây sau khi vượt qua địa vực đầy tinh hài.","detail":"Phần hạch tâm chân chính bên trong Đế Thành. Từ khu vực ngoài phải vượt qua địa vực rộng lớn như đang băng qua vũ trụ, đầy tinh hài, mới tới được cự thành này. Thạch Hạo được người bảo vệ đưa tới đây ở cuối chương.","theLucLienQuan":["Đế Thành"],"nguon":["@c1064"]},{"id":"de-thanh-noi-thanh","name":"Đế Thành nội thành","cn":"","aliases":["Khu vực cốt lõi của Đế Thành"],"capDo":"thanh","parentId":"de-thanh","blurb":"Khu vực cốt lõi của Đế Thành, chỉ những người liên quan tới Thái cổ Minh Ước mới có thể đặt chân vào. Không gian bên trong rộng lớn, chứa nhật nguyệt, Ngân hà, đại tinh và nhiều kiến trúc cổ.","detail":"Phần lớn nội thành chìm trong bóng tối. Nhiều ngôi sao bị chém từ vực ngoại rơi xuống mặt đất nhưng không vỡ nhờ trận văn, còn các kiến trúc cổ khổng lồ lơ lửng giữa tinh thể và những Ngân hà đã hủy diệt. Các tu sĩ đến từ nhiều cổ giới phân tán trấn thủ tại đây, trong đó có người đã ngồi bất động suốt vô số năm.","theLucLienQuan":["Đế Thành","Lực lượng trấn thủ Đế Thành của Cửu Thiên Thập Địa"],"nguon":["@c1065"]},{"id":"de-thanh-ngoai-thanh","name":"Đế Thành ngoại thành","cn":"","aliases":[],"capDo":"thanh","parentId":"de-thanh","blurb":"Khu vực bên ngoài của Đế Thành, có quy mô tương tự nội thành và cũng được xây dựng từ các ngôi sao. Đây không phải khu vực cốt lõi liên quan trực tiếp tới Thái cổ Minh Ước.","detail":"Ngoại thành là phần Thạch Hạo đã đi qua trước khi dùng ba mảnh cốt hợp thành trận đài tiếp dẫn. Quy mô của khu vực này rất lớn nhưng vẫn tách biệt với nơi quan trọng nhất của Đế Thành.","theLucLienQuan":["Đế Thành"],"nguon":["@c1065"]},{"id":"co-dien-truyen-tong-tai-vo-luong-thien","name":"Cổ điện truyền tống tại Vô Lượng Thiên","cn":"","aliases":[],"capDo":"khac","parentId":"vo-luong-thien","blurb":"Cung điện truyền tống khổng lồ lơ lửng trong hư không tại Vô Lượng Thiên.","detail":"Cổ điện rộng hơn mười ngàn dặm, bên trong đặt đạo đài xương thú trắng như ngọc. Bên ngoài cặp cửa đồng cao hơn ngàn dặm là nơi Bạch Mi lão nhân trấn giữ và tiếp nhận những tu sĩ bị đưa tới chịu phạt.","theLucLienQuan":[],"nguon":["@c1066"]},{"id":"khong-gian-truc-xuat","name":"Không gian trục xuất","cn":"","aliases":[],"capDo":"gioi-nho","parentId":"vo-luong-thien","blurb":"Thế giới kỳ dị dùng để giam giữ và trừng phạt những tu sĩ bị xác định là phạm lỗi.","detail":"Không gian này có hồ nước và vùng đất rộng lớn, bị phong tỏa khỏi bên ngoài. Người bị đưa vào phải tự tìm cách thoát ra; một số thiên tài đã mắc kẹt tại đây từ vài năm tới hơn trăm năm.","theLucLienQuan":[],"nguon":["@c1066"]},{"id":"vung-giam-giu-co-co-dao-dai","name":"Vùng giam giữ có cổ đạo đài","cn":"","capDo":"gioi-nho","parentId":"khong-gian-truc-xuat","blurb":"Không gian quỷ dị không thấy điểm cuối hoặc lối thoát, từng giam giữ nhiều tu sĩ và thiên tài trong nhiều năm.","detail":"Tại trung tâm vùng giam giữ có một cổ đạo đài mô phỏng Đăng Tiên Đài. Thạch Hạo dùng ba đạo tiên khí kích hoạt cổ đài, kết thành đại đạo chi hoa rồi mở thông đạo màu bạc đưa toàn bộ những người bị nhốt ra ngoài.","theLucLienQuan":[],"nguon":["@c1067"]},{"id":"thai-so-co-quang","name":"Thái Sơ cổ quáng","cn":"","aliases":["Ma khoáng","Tà khoáng"],"capDo":"khac","parentId":"vo-luong-thien","blurb":"Một cổ quáng cực kỳ nguy hiểm tại Vô Lượng Thiên, vừa chứa cơ duyên kéo dài sinh mệnh vừa chôn vùi nhiều cao thủ.","detail":"Thái Sơ cổ quáng còn được gọi là Ma khoáng hoặc Tà khoáng, có thể khai thác sinh mệnh chi thạch và ẩn chứa cơ duyên kéo dài sinh mệnh. Nơi này nổi tiếng hiểm ác, được truyền là phần mộ của nhiều vị Tiên Vương. Một cao thủ trấn thủ khu cổ địa ép Thạch Hạo tới đây khai thác sinh mệnh chi thạch.","theLucLienQuan":[],"nguon":["@c1067","@c1081"]},{"id":"thanh-tho-thien-than-thu-vien","name":"Thánh thổ Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"vo-luong-thien","blurb":"Thánh thổ nơi Thiên Thần Thư Viện được xác lập, gần đây liên tục có cao thủ lui tới.","detail":"Khu vực được bảo quang, ráng lành, long khí và tiên vụ bao phủ, trở thành tâm điểm chú ý sau khi vị trí của Thiên Thần Thư Viện được xác định.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1068"]},{"id":"tien-gia-dong-phu","name":"Tiên gia động phủ","cn":"","capDo":"khac","parentId":null,"blurb":"Môi trường tu luyện quý hiếm với số lượng suất tiến vào bị hạn chế.","detail":"Tiên gia động phủ có thể tẩm bổ tiên khí, rèn đúc thánh cốt, tái tạo huyết nhục và giúp người tu hành tiếp tục lột xác.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1068"]},{"id":"vung-phe-tich-sat-tran-ngoai-vuc","name":"Vùng phế tích sát trận ngoài vực","cn":"","aliases":[],"capDo":"vuc","parentId":"vo-luong-thien","blurb":"Một vùng tinh không tối lạnh chứa tàn tích của sát trận cổ từng được tuyên bố có thể chém thần diệt tiên.","detail":"Khu vực rải rác hài cốt, thiên thạch, binh khí vỡ, đại kỳ và trận văn cổ. Các tàn vật vẫn có thể bộc phát sát lực, nghiền nát lưu tinh, phá hủy thuyền hoặc kích hoạt lực truyền tống đưa mục tiêu vào sâu trong vũ trụ.","theLucLienQuan":["Thế lực Xích Huyết hào"],"nguon":["@c1069"]},{"id":"thai-so-tinh","name":"Thái Sơ tinh","cn":"","aliases":["Thái Sơ ngôi sao","Thái Sơ Tinh thần"],"capDo":"tinh-cau","parentId":"vo-luong-thien","blurb":"Hành tinh hoang vu ngoài vực, nơi Thái Sơ cổ quáng tọa lạc và nhiều thế lực tập trung khai thác thần liệu.","detail":"Thái Sơ tinh cháy đen, không có cây cỏ và thiếu nguồn nước. Tương truyền các giáo từng luyện hóa toàn bộ vùng đất rộng mười vạn dặm quanh Thái Sơ cổ quáng thành hành tinh rồi đưa ra vực ngoại, nhưng không trực tiếp chạm vào cổ quáng.","theLucLienQuan":["Thế lực Xích Huyết hào"],"nguon":["@c1069"]},{"id":"thien-than-thu-vien-dia-diem","name":"Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"cuu-thien-thap-dia","blurb":"Nơi quy tụ thiên kiêu từ Cửu Thiên Thập Địa và là đích đến Thạch Hạo muốn tiếp cận thông qua giao dịch với Vương tộc.","detail":"Thiên Thần Thư Viện sở hữu nhiều tài nguyên tu luyện quý hiếm như tiên gia động phủ, Hoàng Huyết trì, Trường Sinh dược và ngộ đạo đài. Những tài nguyên này được ưu tiên cho các học viên mạnh nhất, khiến sự cạnh tranh trong thư viện đặc biệt khốc liệt.","theLucLienQuan":["Thiên Thần Thư Viện","Vương tộc"],"nguon":["@c1071"]},{"id":"khu-khai-thac-ngoai-thai-so-co-quang","name":"Khu khai thác ngoài Thái Sơ cổ quáng","cn":"","capDo":"khac","parentId":"thai-so-tinh","blurb":"Vùng khai thác nằm trong dãy núi khô héo quanh Thái Sơ cổ quáng, có nhiều hố sâu do nô lệ đào bới.","detail":"Bí lực từ Thái Sơ cổ quáng khiến đất đá trong khu vực trở nên cứng hơn pháp khí. Khi bị mang ra khỏi phạm vi ảnh hưởng, đất đá lại mất đặc tính này và trở nên dễ vỡ.","theLucLienQuan":["Vương tộc","Liên minh thăm dò của các thế gia và cổ giáo"],"nguon":["@c1072"]},{"id":"loi-vao-thai-so-co-quang","name":"Lối vào Thái Sơ cổ quáng","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Cửa mỏ đen như vực sâu, được bao phủ bởi trường vực và sát cơ chết người.","detail":"Trường vực tại lối vào có thể cầm cố sinh linh, khiến mưa sáng dễ dàng xuyên thủng thân thể và Nguyên Thần của đoàn tử sĩ. Bên trong cửa mỏ còn có sát cơ ngập trời, xương trắng, xác ướp cổ và khí tức đủ nghiền nát người không được bảo vệ.","theLucLienQuan":["Liên minh thăm dò của các thế gia và cổ giáo"],"nguon":["@c1072"]},{"id":"co-lo-trong-hu-khong","name":"Cổ lộ trong hư không","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Một cổ lộ cụt xuất hiện giữa hư không và hỗn độn trong Thái Sơ cổ quáng. Vô số thiên binh thiên tướng mặc giáp đi trên con đường này rồi biến mất.","detail":"Thạch Hạo nhìn thấy đoàn binh tướng cổ xưa giẫm lên con đường cụt và tiến xa giữa hư không, nhưng không thể tiếp cận để kiểm chứng cảnh tượng quỷ dị.","theLucLienQuan":[],"nguon":["@c1073"]},{"id":"khu-vuc-tien-vu-va-duoc-huong","name":"Khu vực tiên vụ và dược hương","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Vùng sâu trong Thái Sơ cổ quáng tràn ngập tiên vụ, sinh khí an lành và dược hương nồng đậm. Quang vũ cùng ráng màu xuất hiện tại nơi số lượng thi hài giảm dần rồi hoàn toàn biến mất.","detail":"Sinh khí tại đây khiến cơ thể Thạch Hạo khoan khoái và thương thế có dấu hiệu khép lại. Từ dược hương vượt trên thần dược, hắn xác định khu vực này có một cây bất hủ tiên dược nghi là Trường Sinh dược.","theLucLienQuan":[],"nguon":["@c1073"]},{"id":"ao-truong-sinh-dich","name":"Ao Trường Sinh dịch","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Một ao nhỏ rộng khoảng năm thước vuông nằm trong Thái Sơ cổ quáng, chứa Trường Sinh dịch do lớp thân cũ của tiên dược hòa với thần tuyền.","detail":"Ao chứa chất lỏng óng ánh, hỗn độn khí, ráng lành và mưa ánh sáng. Lá, thân và rễ do Trường Sinh dược niết bàn bỏ lại đang tan chảy trong nước, tạo thành nước thuốc giúp Thạch Hạo chữa trị thương thế.","theLucLienQuan":[],"nguon":["@c1074"]},{"id":"tien-duoc-tri-trong-thai-so-co-quang","name":"Tiên dược trì trong Thái Sơ cổ quáng","cn":"","aliases":[],"capDo":"khac","parentId":"thai-so-co-quang","blurb":"Bảo trì nằm trong Thái Sơ cổ quáng, chứa Trường Sinh Dịch do Trường Sinh Dược lột xác tạo thành. Đây là nơi Thạch Hạo bế quan và nuôi dưỡng đạo quả trên Đại đạo chi hoa.","detail":"Sau khi đạo quả thứ nhất kết thành sinh linh, trong trì vẫn còn hơn nửa lượng Trường Sinh Dịch. Thạch Hạo tiếp tục ở lại đây bế quan, dự định làm xuất hiện đóa Đại đạo chi hoa thứ hai để kiểm chứng suy đoán về con đường tu hành của mình.","theLucLienQuan":[],"nguon":["@c1076"]},{"id":"thai-son-co-quang","name":"Thái Sơn cổ quáng","cn":"","aliases":[],"capDo":"khac","parentId":null,"blurb":"Cổ khoáng u ám có trận văn bảo vệ kết cấu và ẩn chứa lực lượng kỳ dị trong nơi sâu xa.","detail":"Đây là nơi Thạch Hạo giao chiến với năm cao thủ Vô Lượng Thiên. Khi Cửu Hoàng lô bay về lối ra, cổ khoáng phát sinh cộng hưởng và vang lên kinh văn Lục Đạo Luân Hồi đại pháp, khiến Thạch Hạo nghi ngờ nơi đây còn chôn giấu nhiều bí mật.","theLucLienQuan":["Vô Lượng Thiên","Chí Tôn cung điện"],"nguon":["@c1079"]},{"id":"co-dong-sau-trong-thai-so-co-quang","name":"Cổ động sâu trong Thái Sơ cổ quáng","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Cổ động tối đen nằm sâu trong Thái Sơ cổ quáng, nơi vọng ra tiếng tụng Lục Đạo Luân Hồi Thiên Công.","detail":"Đại đạo thần âm phiêu miểu phát ra từ cổ động hấp dẫn Thạch Hạo tiến gần. Trực giác của hắn đồng thời cảnh báo rằng tiếp tục xâm nhập có thể dẫn tới hình thần đều diệt.","theLucLienQuan":[],"nguon":["@c1080"]},{"id":"khu-vuc-phat-ra-tieng-tung-kinh","name":"Khu vực phát ra tiếng tụng kinh","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Vùng tối nguy hiểm nằm sâu trong Thái Sơ cổ quáng, nơi từng vọng ra tiếng tụng kinh.","detail":"Khu vực khiến Thạch Hạo cảm thấy kề sát tử vong và làm di hài nhện đen run rẩy phủ phục, không dám vượt qua ranh giới.","theLucLienQuan":[],"nguon":["@c1081"]},{"id":"hac-uyen-trong-thai-so-co-quang","name":"Hắc uyên trong cổ khoáng","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Không gian rộng lớn và tối tăm trong vùng sâu Thái Sơ cổ quáng.","detail":"Nơi này giống đường vào địa ngục, có nhiều di hài mang mắt xanh lục, gồm những sinh linh giống rồng và một di hài nghi giống Chu Tước.","theLucLienQuan":[],"nguon":["@c1081"]},{"id":"cung-dien-co-mau-den","name":"Cung điện cổ màu đen","cn":"","aliases":["Cung điện màu đen","Cổ điện màu đen trong Thái Sơ cổ quáng"],"capDo":"khac","parentId":"thai-so-co-quang","blurb":"Kiến trúc cổ bí ẩn nằm ở cuối đường sâu trong Thái Sơ cổ quáng.","detail":"Khí thế trong cung điện đủ đánh văng và gần nghiền nát Thạch Hạo. Bên trong có sáu bóng người mang sáu tư thế tu hành hoặc kết ấn khác nhau, gợi liên hệ với Lục Đạo Luân Hồi Thiên Công.","theLucLienQuan":["Chí Tôn cung điện"],"nguon":["@c1081"]},{"id":"vung-khoi-xam-noi-sau-co-dong","name":"Vùng khói xám nơi sâu cổ động","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Khu vực bí ẩn nằm sâu trong Thái Sơ cổ quáng, bị khói xám che phủ và không thể nhìn thấu. Nơi đây có một bóng người chí cao ngồi xếp bằng cùng sức mạnh có khả năng nhằm vào Vạn Linh Đồ.","detail":"Thạch Hạo chỉ có thể cảm nhận mơ hồ một người đang ngồi xếp bằng trong khói xám. Nguy cơ từ sức mạnh bí ẩn tại đây khiến hắn từ bỏ ý định xông sâu hơn để tránh họa sát thân.","theLucLienQuan":[],"nguon":["@c1085"]},{"id":"khu-vuc-an-toan-trong-thai-so-co-quang","name":"Khu vực an toàn trong Thái Sơ cổ quáng","cn":"","capDo":"khac","parentId":"thai-so-co-quang","blurb":"Phạm vi tương đối an toàn mà học sinh Thiên Thần Thư Viện có thể thăm dò trong Thái Sơ cổ quáng. Họ tìm kiếm đồng môn mất tích tại đây nhưng không thu được kết quả.","detail":"Nhóm học sinh chỉ dám tìm kiếm trong khu vực này vì khí tức đáng sợ từ nơi sâu khiến họ không dám tới gần. Trong những ngày Thạch Hạo bế quan, họ vẫn không phát hiện tung tích các đồng môn mất tích.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1086"]},{"id":"ao-hoang-huyet","name":"Hoàng Huyết trì","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Một ao thuộc Thiên Thần Thư Viện, được cho là lưu giữ máu Phượng Hoàng để lại sau khi niết bàn.","detail":"Hoàng Huyết mà Thạch Hạo lấy từ một thanh niên được suy đoán có nguồn gốc từ nơi này. Ao được mô tả là chứa một trì huyết do Phượng Hoàng niết bàn lưu lại.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1087"]},{"id":"tinh-vuc-co-chien-truong","name":"Tinh vực cổ chiến trường","cn":"","capDo":"vuc","parentId":"cuu-thien-thap-dia","blurb":"Tinh vực nằm giữa Thái Sơ ngôi sao và Vô Lượng Thiên, mang dấu tích của chiến trường cổ.","detail":"Không gian này có nhiều tàn tích, trận văn và khe nứt không gian. Tu sĩ tự vượt qua rất dễ lạc đường hoặc gặp hiểm họa, khiến Thạch Hạo phải chờ chiến thuyền để trở về Vô Lượng Thiên.","theLucLienQuan":[],"nguon":["@c1089"]},{"id":"cuu-thien","name":"Cửu Thiên","cn":"","capDo":"gioi-dien","parentId":"cuu-thien-thap-dia","blurb":"Khu vực gồm chín tầng trời nằm phía trên Thập Địa, có lãnh thổ rộng lớn và điều kiện tu hành vượt trội.","detail":"Cửu Thiên được mô tả rộng lớn hơn Thập Địa, có điều kiện tu hành tốt hơn và sản sinh nhiều nhân kiệt. Vô Lượng Thiên là một tầng trong khu vực này.","theLucLienQuan":[],"nguon":["@c1090"]},{"id":"tinh-than-hai","name":"Tinh Thần hải","cn":"","capDo":"vuc","parentId":"vo-luong-thien","blurb":"Vùng đất rộng lớn trên Vô Lượng Thiên được hình thành từ vô số sao băng rơi xuống trong một trận đại chiến cổ xưa.","detail":"Tinh Thần hải rộng tương đương khoảng mười châu của ba ngàn đạo châu. Những sao băng được đại năng luyện hóa thành sơn mạch, còn dưới lòng đất chôn vùi mảnh vỡ chí bảo, máu xương cường giả và nhiều tiên gia động phủ; Thiên Thần Thư Viện tọa lạc tại vùng cát địa nhất nơi đây.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1090"]},{"id":"son-mon-thien-than-thu-vien","name":"Sơn môn Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"tinh-than-hai","blurb":"Tịnh thổ và sơn môn của Thiên Thần Thư Viện, nơi vô số tuấn kiệt tụ tập tìm cơ hội đi theo các đệ tử nòng cốt.","detail":"Khu vực có những dãy núi như vạn Chân Long ngủ đông, cung điện, thác thần, thánh dược, thần dược và cổ thần giao. Phía dưới sơn mạch được truyền là có một tiên gia động phủ từ kỷ nguyên trước sắp xuất thế.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1090","@c1093"]},{"id":"noi-vien-thien-than-thu-vien","name":"Nội viện Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Khu vực bên trong Thiên Thần Thư Viện, có nhiều núi lớn do các ngôi sao hóa thành và những vùng linh thổ dành cho đệ tử chân truyền.","detail":"Nội viện là một vùng tịnh thổ rộng lớn với núi sao phóng thích tinh khí trời đất, cung điện, thác nước, thần dược và nhiều khu linh thổ.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1091"]},{"id":"noi-sau-trong-thien-than-thu-vien","name":"Nơi sâu trong Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"noi-vien-thien-than-thu-vien","blurb":"Khu vực sâu bên trong Thiên Thần Thư Viện, nơi phát ra hai tiếng nói có thái độ trái ngược đối với Nguyên Thanh.","detail":"Sau khi Nguyên Thanh đưa hậu nhân vào viện, một tiếng quát từ nơi sâu bên trong công khai hỏi tội ông. Ngay sau đó, một tiếng nói khác yêu cầu Nguyên Thanh rời đi trước, bộc lộ sự bất đồng trong tầng cao thư viện.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1093"]},{"id":"dao-than-sau-trong-thien-than-thu-vien","name":"Đảo thần sâu trong thư viện","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Một đảo thần lơ lửng trên trời ở nơi sâu trong Thiên Thần Thư Viện. Đảo bị hỗn độn khí che phủ và là nơi tiếng nói già nua triệu Nguyên Thanh tới.","detail":"Đảo thần nằm giữa khu vực có lầu quỳnh điện ngọc ở sâu trong thư viện, lơ lửng giữa trời và bị hỗn độn khí che lấp. Từ nơi này, một tiếng nói già nua truyền ra để triệu Nguyên Thanh tới.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1094"]},{"id":"thanh-hi-u-lam","name":"Thanh Hi U Lâm","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Động phủ và đạo thổ của Vương Hi trong Thiên Thần Thư Viện, nằm giữa mười ngọn thần nhạc.","detail":"Khu vực có nhiều cổ dược, thiên địa tinh hoa và khí tức tiên đạo bản nguyên. Mười đạo thần mạch dưới đất cùng hội tụ, nuôi dưỡng động phủ trung tâm và các ngọn thần nhạc xung quanh.","theLucLienQuan":["Thiên Thần Thư Viện","Vương gia"],"nguon":["@c1095"]},{"id":"muoi-ngon-than-nhac-cua-vuong-hi","name":"Mười ngọn thần nhạc của Vương Hi","cn":"","capDo":"khac","parentId":"thanh-hi-u-lam","blurb":"Mười đại nhạc cao vút bao quanh động phủ Thanh Hi U Lâm, được dùng làm nơi đặt chân cho những người Vương Hi lựa chọn.","detail":"Các ngọn thần nhạc mang nhiều dị tượng như thanh quang, long khí, tử khí và xích hà. Tổ mạch bên dưới chúng cùng hội tụ về động phủ trung tâm của Vương Hi.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1095"]},{"id":"dong-phu-trong-thach-bich","name":"Động phủ trong thạch bích","cn":"","capDo":"khac","parentId":"thanh-hi-u-lam","blurb":"Tu hành thánh thổ nằm trong thạch bích tại trung tâm Thanh Hi U Lâm.","detail":"Động phủ được mười mạch tổ mạch bồi dưỡng, chứa thiên địa tinh hoa đậm đặc như nước cùng khí tức tiên đạo bản nguyên. Phía sâu bên trong còn có tiểu thiên địa riêng của Vương Hi.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1095"]},{"id":"tieu-thien-dia-rieng-cua-vuong-hi","name":"Tiểu thiên địa riêng của Vương Hi","cn":"","capDo":"gioi-nho","parentId":"dong-phu-trong-thach-bich","blurb":"Khu vực nghỉ ngơi và tu hành riêng của Vương Hi nằm sâu trong động phủ Thanh Hi U Lâm.","detail":"Lối vào có cửa đá cùng phong ấn ngăn người ngoài tùy tiện tiến vào. Trong thạch thất trung tâm đặt giường kỳ thạch có khả năng hỗ trợ nhập ngộ đạo cảnh.","theLucLienQuan":["Thiên Thần Thư Viện","Vương gia"],"nguon":["@c1095"]},{"id":"dong-phu-cua-vuong-hi","name":"Động phủ của Vương Hi","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Một vùng tịnh thổ thuộc về Vương Hi trong Thiên Thần Thư Viện.","detail":"Động phủ có hào quang dâng trào và sương mù hỗn độn. Nơi này được xem là cấm địa đối với nhóm đệ tử hiện diện, khiến hậu duệ Thái cổ ma hùng không dám tùy tiện bước vào.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1097"]},{"id":"huyet-tri-thien-than-thu-vien","name":"Huyết Trì","cn":"","capDo":"khac","parentId":"noi-vien-thien-than-thu-vien","blurb":"Nơi số ít nhân vật đứng đầu Thiên Thần Thư Viện được tắm rửa bằng lượng lớn Hoàng huyết.","detail":"Vương Hi, Lục Đà, Phong Hành Thiên và một số ít người có tư cách tiến vào Huyết Trì. Những đệ tử khác phải có biểu hiện hoặc công lao nổi bật mới được ban thưởng Hoàng huyết.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1098"]},{"id":"tien-gia-chien-truong","name":"Tiên gia chiến trường","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường mà Vương Hi dự định đưa Thạch Hạo tới chinh chiến.","detail":"Lục Đà, Phong Hành Thiên và những cao thủ khác cũng có thể dẫn người tới đây. Thông tin này khiến Thạch Hạo từ chỗ không hứng thú chuyển sang cân nhắc tham gia để đối phó một số người.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1098"]},{"id":"nha-da-cua-thach-hao","name":"Nhà đá của Thạch Hạo","cn":"","capDo":"khac","parentId":"noi-vien-thien-than-thu-vien","blurb":"Nơi Thạch Hạo bế quan tu luyện trong Thiên Thần Thư Viện.","detail":"Thạch Hạo kết thúc quá trình thể ngộ đóa Đại đạo chi hoa thứ hai tại đây rồi xuất quan gặp Vương Hi.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1100"]},{"id":"than-duoc-vien","name":"Thần dược viên","cn":"","capDo":"khac","parentId":"noi-vien-thien-than-thu-vien","blurb":"Vườn thuốc được bảo vệ nghiêm ngặt của Thiên Thần Thư Viện.","detail":"Một tuyệt thế đại trận che chắn khu vườn, khiến người đến gần cũng không thể nhìn thấy dược thảo bên trong.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1100"]}]};
